  { app: 'Figma', seatCostMonthly: 15, seats: [ { user: 'a.kim', lastLoginDaysAgo: 3 }, { user: 'b.ross', lastLoginDaysAgo: 92 }, { user: 'c.diaz', lastLoginDaysAgo: 61 }, { user: 'd.wu', lastLoginDaysAgo: 8 } ] },
  { app: 'Zoom Pro', seatCostMonthly: 16, seats: [ { user: 'a.kim', lastLoginDaysAgo: 1 }, { user: 'e.moss', lastLoginDaysAgo: 130 } ] },
  { app: 'Miro', seatCostMonthly: 10, seats: [ { user: 'b.ross', lastLoginDaysAgo: 47 }, { user: 'f.chan', lastLoginDaysAgo: 12 }, { user: 'g.ito', lastLoginDaysAgo: 210 } ] }
] } }];

// Inactive threshold 45 days: long enough to skip vacations, short enough to matter
const { apps } = $input.first().json;
const THRESHOLD = 45;
let monthly = 0; const sections = [];
for (const a of apps) {
  const idle = a.seats.filter(s => s.lastLoginDaysAgo > THRESHOLD);
  if (!idle.length) continue;
  const save = idle.length * a.seatCostMonthly;
  monthly += save;
  sections.push(a.app + ' (' + idle.length + ' of ' + a.seats.length + ' seats idle, $' + save + '/mo):\n' + idle.map(s => '  ' + s.user + ' - last login ' + s.lastLoginDaysAgo + ' days ago').join('\n'));
}
if (!sections.length) return [];
const body = 'License reclaim sweep (idle > ' + THRESHOLD + ' days):\n\n' + sections.join('\n\n') + '\n\nReclaimable: $' + monthly + '/month ($' + monthly * 12 + '/year)\n\nProcess: confirm with the manager, downgrade or reassign the seat, and note it before the renewal call. Walking into a vendor negotiation knowing your true utilization is the whole game.';
return [{ json: { subject: 'License reclaim: $' + monthly * 12 + '/year on the table', body } }];
